window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d2a1be0044d76d27"]={"versions": [{"id": "FIG-d2a1be0044d76d27", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram, Rahmenkopf <code>stm LinNm State</code>) zur Spezifikation des Zustandsautomaten des AUTOSAR Classic Platform Basissoftware-Moduls LIN Network Management (<code>LinNm</code>) für einen LIN-Kanal (<code>Lin Network</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Initialpseudozustand:</strong> Startpunkt für das Netzwerk (<code>Lin Network</code>).</li>\n<li><strong>Zustände:</strong></li>\n<li><code>NM_STATE_UNINIT</code>: Uninitialisierter Zustand des Moduls LinNm.</li>\n<li><code>NM_STATE_BUS_SLEEP</code>: Schlafzustand des LIN-Busses bzw. Ruhemodus ohne aktive Kommunikation.</li>\n<li><code>NM_STATE_NORMAL_OPERATION</code>: Zustand des regulären operativen Netzwerkbetriebs.</li>\n<li><strong>Schnittstellen & Trigger:</strong> Funktionsaufrufe / API-Trigger <code>LinNm_Init</code>, <code>LinNm_NetworkRequest</code>, <code>LinNm_PassiveStartUp</code> sowie <code>LinNm_NetworkRelease</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Ausgehend vom Initialknoten (<code>Lin Network</code>) wechselt das Modul in den Zustand <code>NM_STATE_UNINIT</code>.</li>\n<li>Durch den Aufruf von <code>LinNm_Init</code> erfolgt die Initialisierung und der Übergang in den Zustand <code>NM_STATE_BUS_SLEEP</code>.</li>\n<li>Aus <code>NM_STATE_BUS_SLEEP</code> führen zwei Transitionen in den Zustand <code>NM_STATE_NORMAL_OPERATION</code>:</li>\n<li>Aufruf von <code>LinNm_NetworkRequest</code> (aktive Netzanforderung).</li>\n<li>Aufruf von <code>LinNm_PassiveStartUp</code> (passiver Start des Netzwerks).</li>\n<li>Aus <code>NM_STATE_NORMAL_OPERATION</code> führt der Aufruf von <code>LinNm_NetworkRelease</code> zurück in den Zustand <code>NM_STATE_BUS_SLEEP</code>.</li>\n<li>Sämtliche Transitionen sind im Diagramm mit gestrichelten Wirkungslinien dargestellt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert verbindlich die drei Hauptzustände des LinNm sowie die zulässigen Zustandsübergänge über die LinNm-APIs. In dieser Fassung kann der Zustand <code>NM_STATE_NORMAL_OPERATION</code> nach einem Aufruf (insbesondere auch nach <code>LinNm_PassiveStartUp</code>) ausschließlich durch den expliziten Aufruf von <code>LinNm_NetworkRelease</code> wieder in Richtung <code>NM_STATE_BUS_SLEEP</code> verlassen werden. Ein automatischer zeitgesteuerter Rückfall bei passivem Start ist im Zustandsdiagramm nicht modelliert.</p>"}, {"id": "FIG-795b199b3a8ffd3a", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram, Rahmenkopf <code>stm LinNm State</code>) zur Spezifikation des Zustandsautomaten des AUTOSAR Classic Platform Basissoftware-Moduls LIN Network Management (<code>LinNm</code>) für einen LIN-Kanal (<code>Lin Network</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Initialpseudozustand:</strong> Startpunkt für das Netzwerk (<code>Lin Network</code>).</li>\n<li><strong>Zustände:</strong></li>\n<li><code>NM_STATE_UNINIT</code>: Uninitialisierter Zustand des Moduls LinNm.</li>\n<li><code>NM_STATE_BUS_SLEEP</code>: Schlafzustand des LIN-Busses bzw. Ruhemodus ohne aktive Kommunikation.</li>\n<li><code>NM_STATE_NORMAL_OPERATION</code>: Zustand des regulären operativen Netzwerkbetriebs.</li>\n<li><strong>Schnittstellen & Trigger:</strong> Funktionsaufrufe / API-Trigger <code>LinNm_Init</code>, <code>LinNm_NetworkRequest</code>, <code>LinNm_PassiveStartUp</code> sowie <code>LinNm_NetworkRelease</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Ausgehend vom Initialknoten (<code>Lin Network</code>) wechselt das Modul in den Zustand <code>NM_STATE_UNINIT</code>.</li>\n<li>Durch den Aufruf von <code>LinNm_Init</code> erfolgt die Initialisierung und der Übergang in den Zustand <code>NM_STATE_BUS_SLEEP</code>.</li>\n<li>Aus <code>NM_STATE_BUS_SLEEP</code> führen zwei Transitionen in den Zustand <code>NM_STATE_NORMAL_OPERATION</code>:</li>\n<li>Aufruf von <code>LinNm_NetworkRequest</code> (aktive Netzanforderung).</li>\n<li>Aufruf von <code>LinNm_PassiveStartUp</code> (passiver Start des Netzwerks).</li>\n<li>Aus <code>NM_STATE_NORMAL_OPERATION</code> führt der Aufruf von <code>LinNm_NetworkRelease</code> zurück in den Zustand <code>NM_STATE_BUS_SLEEP</code>.</li>\n<li>Sämtliche Transitionen sind im Diagramm mit gestrichelten Wirkungslinien dargestellt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert verbindlich die drei Hauptzustände des LinNm sowie die zulässigen Zustandsübergänge über die LinNm-APIs. In dieser Fassung kann der Zustand <code>NM_STATE_NORMAL_OPERATION</code> nach einem Aufruf (insbesondere auch nach <code>LinNm_PassiveStartUp</code>) ausschließlich durch den expliziten Aufruf von <code>LinNm_NetworkRelease</code> wieder in Richtung <code>NM_STATE_BUS_SLEEP</code> verlassen werden. Ein automatischer zeitgesteuerter Rückfall bei passivem Start ist im Zustandsdiagramm nicht modelliert.</p>"}, {"id": "FIG-ea50d66c1b597b3f", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm zur Spezifikation des Zustandsautomaten des AUTOSAR Classic Platform Basissoftware-Moduls LIN Network Management (<code>LinNm</code>) für einen LIN-Kanal (<code>Lin Network</code>), dargestellt ohne äußeren UML-Rahmen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Initialpseudozustand:</strong> Startpunkt für das LIN-Netzwerk (<code>Lin Network</code>).</li>\n<li><strong>Zustände:</strong></li>\n<li><code>NM_STATE_UNINIT</code>: Uninitialisierter Zustand.</li>\n<li><code>NM_STATE_BUS_SLEEP</code>: Schlafzustand des LIN-Netzwerks.</li>\n<li><code>NM_STATE_NORMAL_OPERATION</code>: Operativer Betriebszustand.</li>\n<li><strong>Schnittstellen, Events & Trigger:</strong></li>\n<li>API-Aufrufe: <code>LinNm_Init</code>, <code>LinNm_PassiveStartUp</code>, <code>LinNm_NetworkRequest</code>, <code>LinNm_NetworkRelease</code>.</li>\n<li>Zeitereignis / interner Event: <code>LinNmTimeoutTime expired in passive startup</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Vom Initialknoten (<code>Lin Network</code>) führt der Übergang in <code>NM_STATE_UNINIT</code>.</li>\n<li>Der API-Aufruf <code>LinNm_Init</code> überführt die State Machine in <code>NM_STATE_BUS_SLEEP</code>.</li>\n<li>Von <code>NM_STATE_BUS_SLEEP</code> nach <code>NM_STATE_NORMAL_OPERATION</code> existieren zwei gerichtete Transitionen:</li>\n<li>Trigger <code>LinNm_PassiveStartUp</code></li>\n<li>Trigger <code>LinNm_NetworkRequest</code></li>\n<li>Von <code>NM_STATE_NORMAL_OPERATION</code> zurück nach <code>NM_STATE_BUS_SLEEP</code> existieren zwei distinkte Rücktransitionen:</li>\n<li>Trigger <code>LinNmTimeoutTime expired in passive startup</code>: Automatischer Rückfall bei Ablauf des Timers im passiven Startmodus.</li>\n<li>Trigger <code>LinNm_NetworkRelease</code>: Reguläre Freigabe des Netzwerks.</li>\n<li>Sämtliche Transitionen sind als durchgezogene Wirkungslinien mit offenen Pfeilspitzen dargestellt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Festlegung der Zustandsübergänge für das AUTOSAR LinNm. Wesentlich für die Implementierung ist die Unterscheidung der Rückkehrbedingungen nach <code>NM_STATE_BUS_SLEEP</code>: Wurde der Zustand <code>NM_STATE_NORMAL_OPERATION</code> über <code>LinNm_PassiveStartUp</code> erreicht, führt der Ablauf des konfigurierten Timers (<code>LinNmTimeoutTime expired in passive startup</code>) autonom zurück in den Ruhezustand; bei regulärer Anforderung beendet <code>LinNm_NetworkRelease</code> den Betriebszustand.</p>"}, {"id": "FIG-64f5b053d9268313", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm zur Spezifikation des Zustandsautomaten des AUTOSAR Classic Platform Basissoftware-Moduls LIN Network Management (<code>LinNm</code>) für einen LIN-Kanal (<code>Lin Network</code>), dargestellt ohne äußeren UML-Rahmen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Initialpseudozustand:</strong> Startpunkt für das LIN-Netzwerk (<code>Lin Network</code>).</li>\n<li><strong>Zustände:</strong></li>\n<li><code>NM_STATE_UNINIT</code>: Uninitialisierter Zustand.</li>\n<li><code>NM_STATE_BUS_SLEEP</code>: Schlafzustand des LIN-Netzwerks.</li>\n<li><code>NM_STATE_NORMAL_OPERATION</code>: Operativer Betriebszustand.</li>\n<li><strong>Schnittstellen, Events & Trigger:</strong></li>\n<li>API-Aufrufe: <code>LinNm_Init</code>, <code>LinNm_PassiveStartUp</code>, <code>LinNm_NetworkRequest</code>, <code>LinNm_NetworkRelease</code>.</li>\n<li>Zeitereignis / interner Event: <code>LinNmTimeoutTime expired in passive startup</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Vom Initialknoten (<code>Lin Network</code>) führt der Übergang in <code>NM_STATE_UNINIT</code>.</li>\n<li>Der API-Aufruf <code>LinNm_Init</code> überführt die State Machine in <code>NM_STATE_BUS_SLEEP</code>.</li>\n<li>Von <code>NM_STATE_BUS_SLEEP</code> nach <code>NM_STATE_NORMAL_OPERATION</code> existieren zwei gerichtete Transitionen:</li>\n<li>Trigger <code>LinNm_PassiveStartUp</code></li>\n<li>Trigger <code>LinNm_NetworkRequest</code></li>\n<li>Von <code>NM_STATE_NORMAL_OPERATION</code> zurück nach <code>NM_STATE_BUS_SLEEP</code> existieren zwei distinkte Rücktransitionen:</li>\n<li>Trigger <code>LinNmTimeoutTime expired in passive startup</code>: Automatischer Rückfall bei Ablauf des Timers im passiven Startmodus.</li>\n<li>Trigger <code>LinNm_NetworkRelease</code>: Reguläre Freigabe des Netzwerks.</li>\n<li>Sämtliche Transitionen sind als durchgezogene Wirkungslinien mit offenen Pfeilspitzen dargestellt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Festlegung der Zustandsübergänge für das AUTOSAR LinNm. Wesentlich für die Implementierung ist die Unterscheidung der Rückkehrbedingungen nach <code>NM_STATE_BUS_SLEEP</code>: Wurde der Zustand <code>NM_STATE_NORMAL_OPERATION</code> über <code>LinNm_PassiveStartUp</code> erreicht, führt der Ablauf des konfigurierten Timers (<code>LinNmTimeoutTime expired in passive startup</code>) autonom zurück in den Ruhezustand; bei regulärer Anforderung beendet <code>LinNm_NetworkRelease</code> den Betriebszustand.</p>"}], "trans": [{"from": "FIG-d2a1be0044d76d27", "to": "FIG-795b199b3a8ffd3a", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Das Diagramm wurde mit leicht veränderten Seitenrändern bzw. leicht komprimierter Breite neu gerendert; alle Zustände, Transitionen und Beschriftungen sind identisch erhalten.</li>\n</ul>"}, {"from": "FIG-795b199b3a8ffd3a", "to": "FIG-ea50d66c1b597b3f", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Der UML-Rahmenkopf <code>stm LinNm State</code> und der äußere Diagrammrahmen wurden entfernt.</li>\n<li>Die Transitionspfeile sind nun als durchgezogene statt gestrichelte Linien ausgeführt.</li>\n<li>Eine neue Transition von <code>NM_STATE_NORMAL_OPERATION</code> nach <code>NM_STATE_BUS_SLEEP</code> mit dem Trigger <code>LinNmTimeoutTime expired in passive startup</code> wurde hinzugefügt.</li>\n<li>Die Anordnung der Transitionen zwischen <code>NM_STATE_BUS_SLEEP</code> und <code>NM_STATE_NORMAL_OPERATION</code> wurde umsortiert (von links nach rechts: Rücktransition bei Timeout, <code>LinNm_PassiveStartUp</code>, <code>LinNm_NetworkRequest</code>, <code>LinNm_NetworkRelease</code>).</li>\n</ul>"}, {"from": "FIG-ea50d66c1b597b3f", "to": "FIG-64f5b053d9268313", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
